#!/usr/bin/env node
// Refresh the bundled badge icon catalog from https://ingress.plus/badges.
// The generated file is COMMITTED (icons are hotlinked, no personal data),
// so the browser onboarding flow never needs a cross-origin fetch.
//
// Usage:
//   node scripts/fetch-badge-catalog.mjs                 # fetch live
//   node scripts/fetch-badge-catalog.mjs --html FILE    # parse a saved HTML

import { readFileSync, writeFileSync } from "node:fs";

const args = process.argv.slice(2);
const htmlIdx = args.indexOf("--html");
const html = htmlIdx >= 0 ? readFileSync(args[htmlIdx + 1], "utf8") : await (await fetch("https://ingress.plus/badges")).text();

const catalog = {};
const re = /<img[^>]*alt="([^"]+)"[^>]*src="(\/api\/files\/[^"]+)"/g;
let m;
while ((m = re.exec(html))) {
  catalog[m[1].toLowerCase()] = `https://ingress.plus${m[2]}`;
}
if (Object.keys(catalog).length < 100) {
  console.error(`Only ${Object.keys(catalog).length} icons found; refusing to overwrite.`);
  process.exit(1);
}

const out = `// AUTO-GENERATED by scripts/fetch-badge-catalog.mjs — do not edit by hand.
// Source: https://ingress.plus/badges (${new Date().toISOString().slice(0, 10)})
// Icon URLs are hotlinked from ingress.plus; no images are stored in this repo.
export const BADGE_CATALOG = ${JSON.stringify(catalog, null, 2)};

// Badges whose catalog alt text does not match the profile naming.
export const SPECIAL_ICONS = {
  "verified": "https://ingress.plus/api/files/i37o5ykupb5voix/io5d30l7v6a2efg/unique_badge_verified_B57B8yzC1a.png?thumb=128x128",
  "avenir shard challenge": "https://ingress.plus/api/files/i37o5ykupb5voix/orb5wfhrrzwyl46/unique_badge_avenir_shard_challenge_LWFgJycZYf.png?thumb=256x256",
  "simulacrum": "https://ingress.plus/api/files/i37o5ykupb5voix/tfzk04jcn2nay3l/unique_badge_simulacrum_HLUX9WITcI.png?thumb=256x256",
};

export const PLACEHOLDER_ICON = "https://ingress.plus/images/badges/placeholder_ribbon.png";
`;
writeFileSync("src/data/badgeCatalog.js", out);
console.log(`Wrote src/data/badgeCatalog.js with ${Object.keys(catalog).length} icons`);
